// ProtecExtintores: fonte completo empacotado para upload com poucos arquivos.
// O conteúdo é extraído como arquivos, nunca executado por eval.
import {readFileSync,writeFileSync,mkdirSync,existsSync,readdirSync,realpathSync,lstatSync,chmodSync} from 'node:fs';
import {resolve,dirname,relative,isAbsolute,sep,posix,join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {tmpdir} from 'node:os';
import {createHash,randomUUID} from 'node:crypto';
import {gzipSync,gunzipSync} from 'node:zlib';
import {execFileSync} from 'node:child_process';

const BUNDLE_SHA256="ac354345c222003e64d99010d57d87c85567a1b02121061e5536de7d52493476";
const BUNDLE_GZIP_BASE64="";
const digest=bytes=>createHash('sha256').update(bytes).digest('hex');
const self=fileURLToPath(import.meta.url),uploadRoot=dirname(self);
export function readProject(){
 const compressed=Buffer.from(BUNDLE_GZIP_BASE64,'base64');
 if(digest(compressed)!==BUNDLE_SHA256)throw Error('O pacote está incompleto. Baixe novamente o ZIP.');
 const project=JSON.parse(gunzipSync(compressed,{maxOutputLength:64*1024*1024}).toString('utf8'));
 if(project.format!==1||!Array.isArray(project.files)||!project.files.length||project.files.length>1000)throw Error('Formato de projeto inválido.');
 const seen=new Set();
 for(const file of project.files){
  const name=file.path;
  if(typeof name!=='string'||!name||name.includes('\\')||/[\x00-\x1f]/.test(name)||isAbsolute(name)||/^[a-z]:/i.test(name)||posix.normalize(name)!==name||name.split('/').some(p=>!p||p==='.'||p==='..')||seen.has(name))throw Error('Caminho inválido no projeto.');
  const bytes=Buffer.from(file.data,'base64');
  if(digest(bytes)!==file.sha256)throw Error('Arquivo corrompido: '+name);
  seen.add(name);
 }
 for(const name of ['site/index.html','api-cloudflare/wrangler.jsonc','android-app/app/build.gradle','scripts/verify-site.mjs'])if(!seen.has(name))throw Error('Falta um arquivo necessário: '+name);
 return project;
}
export function extractProject(destination){
 const project=readProject();
 const target=resolve(destination||join(tmpdir(),'ProtecExtintores-projeto-'+randomUUID().slice(0,8)));
 // Generated source must stay outside the upload folder, including API dependencies.
 const fromUpload=relative(realpathSync(uploadRoot),target);
 if(fromUpload===''||!fromUpload.startsWith('..'+sep)&&fromUpload!=='..'&&!isAbsolute(fromUpload))throw Error('Escolha um destino fora da pasta mínima de envio.');
 if(existsSync(target))throw Error('O destino já existe. Escolha uma pasta nova; os dados existentes foram preservados.');
 mkdirSync(target,{recursive:true});const actualRoot=realpathSync(target);
 for(const file of project.files){
  const output=resolve(actualRoot,file.path),rel=relative(actualRoot,output);
  if(rel==='..'||rel.startsWith('..'+sep)||isAbsolute(rel))throw Error('Destino inválido: '+file.path);
  mkdirSync(dirname(output),{recursive:true});
  const actualParent=relative(actualRoot,realpathSync(dirname(output)));
  if(actualParent==='..'||actualParent.startsWith('..'+sep)||isAbsolute(actualParent))throw Error('Pasta fora do destino.');
  writeFileSync(output,Buffer.from(file.data,'base64'),{flag:'wx'});
  if(process.platform!=='win32')chmodSync(output,file.mode===493?0o755:0o644);
  if(digest(readFileSync(output))!==file.sha256)throw Error('Falha ao conferir a extração: '+file.path);
 }
 console.log('Projeto completo preparado: '+actualRoot);
 console.log(project.files.length+' arquivos conferidos. Para o GitHub, continue usando somente a pasta mínima.');
 return actualRoot;
}
export function repackProject(folder){
 if(!folder)throw Error('Informe a pasta expandida: node ProtecExtintores.mjs reempacotar "PASTA"');
 const root=realpathSync(resolve(folder)),project=readProject();
 // Keep the known source manifest. node_modules and local secrets never enter it.
 for(const file of project.files){
  const input=resolve(root,file.path),stat=lstatSync(input),actual=relative(root,realpathSync(input));
  if(!stat.isFile()||stat.isSymbolicLink()||actual==='..'||actual.startsWith('..'+sep)||isAbsolute(actual))throw Error('Arquivo ausente ou inválido: '+file.path);
  const bytes=readFileSync(input);file.data=bytes.toString('base64');file.sha256=digest(bytes);
 }
 const compressed=gzipSync(Buffer.from(JSON.stringify(project)),{level:9});
 const source=readFileSync(self,'utf8').replace(/^const BUNDLE_SHA256=.*;$/m,()=> 'const BUNDLE_SHA256='+JSON.stringify(digest(compressed))+';').replace(/^const BUNDLE_GZIP_BASE64=.*;$/m,()=> 'const BUNDLE_GZIP_BASE64='+JSON.stringify(compressed.toString('base64'))+';');
 writeFileSync(self,source);console.log('Fonte completo atualizado em ProtecExtintores.mjs. Envie os mesmos 5 arquivos ao GitHub.');
}
export async function checkGithub(){
 const paths=['ProtecExtintores.mjs','.github/workflows/pages.yml','.github/workflows/android-apk.yml'];let missing=0;
 for(const path of paths){
  const local=join(uploadRoot,path);
  if(!existsSync(local))throw Error('Arquivo local ausente: '+path+'. Extraia o ZIP completo em uma pasta nova.');
  const bytes=readFileSync(local),expected=createHash('sha1').update('blob '+bytes.length+'\0').update(bytes).digest('hex');
  const url='https://api.github.com/repos/eusouods/ProtecExtintores/contents/'+path+'?ref=main&check='+Date.now();
  const response=await fetch(url,{headers:{'Accept':'application/vnd.github+json','Cache-Control':'no-cache'},signal:AbortSignal.timeout(15000)});
  if(response.status===404){console.log('FALTA NO CAMINHO CERTO: '+path);missing++;continue;}
  if(!response.ok)throw Error('Não foi possível consultar o GitHub agora (HTTP '+response.status+'). Tente novamente.');
  const data=await response.json();
  if(data.sha!==expected){console.log('VERSÃO DIFERENTE: '+path);missing++;}else console.log('OK: '+path);
 }
 if(missing){console.log('Atualização ainda incompleta. Os YAML precisam estar em .github/workflows, e o .mjs na raiz. Pelo GitHub Desktop, copie o conteúdo da pasta mínima para a raiz clonada, faça Commit e Push origin.');process.exitCode=1;}
 else console.log('Arquivos corretos na main. Confira a execução Publicar ProtecExtintores no GitHub Pages no Actions. Esta checagem não publica a API.');
}
function publishApi(){
 const root=extractProject(),api=join(root,'api-cloudflare');
 console.log('Publicando a API Cloudflare a partir da cópia expandida. Preserve sua autenticação e os segredos existentes.');
 const options={cwd:api,stdio:'inherit',windowsHide:true};
 // The Windows shell receives a fixed command; no path or user input is interpolated.
 if(process.platform==='win32')execFileSync(process.env.ComSpec||'cmd.exe',['/d','/s','/c','npm.cmd ci'],options);
 else execFileSync('npm',['ci'],options);
 const wrangler=join(api,'node_modules/wrangler/bin/wrangler.js');
 const config=readFileSync(join(api,'wrangler.jsonc'),'utf8'),database=config.match(/"database_name"\s*:\s*"([^"\r\n]+)"/)?.[1];
 if(!database)throw Error('Confira o nome do banco no wrangler.jsonc da cópia expandida.');
 execFileSync(process.execPath,[wrangler,'d1','migrations','apply',database,'--remote'],options);
 execFileSync(process.execPath,[wrangler,'deploy'],options);
 console.log('Comandos de publicação concluídos. Confira a URL exibida pelo Wrangler.');
}
if(process.argv[1]&&resolve(process.argv[1])===self){
 try{
  const [command,...args]=process.argv.slice(2);
  if(command==='extrair'){
   if(args.length&&!(args.length===2&&args[0]==='--destino'))throw Error('Use: node ProtecExtintores.mjs extrair [--destino "PASTA_NOVA_FORA_DESTA_PASTA"]');
   extractProject(args[1]);
  }else if(command==='verificar'){const project=readProject();console.log('Pacote íntegro: '+project.files.length+' arquivos-fonte; SHA-256 '+BUNDLE_SHA256);}
  else if(command==='conferir-github'){if(args.length)throw Error('Use: node ProtecExtintores.mjs conferir-github');await checkGithub();}
  else if(command==='api'){if(args.length)throw Error('Use: node ProtecExtintores.mjs api');publishApi();}
  else if(command==='reempacotar')repackProject(args[0]);
  else if(command)throw Error('Comando desconhecido. Use extrair, verificar, conferir-github, api ou reempacotar.');
  else console.log('Envie os 5 arquivos desta pasta ao GitHub. O Actions prepara o site e o APK automaticamente.\nPara publicar a API: node ProtecExtintores.mjs api\nPara extrair os fontes fora desta pasta: node ProtecExtintores.mjs extrair\nPara conferir o pacote: node ProtecExtintores.mjs verificar\nPara conferir os arquivos enviados ao GitHub: node ProtecExtintores.mjs conferir-github');
 }catch(error){console.error('Erro: '+error.message);process.exitCode=1;}
}
